// Filter tasks that are paused awaiting user, compute age, decide tier.
// Source-of-truth for paused tasks is the checkpointer; we treat any task with
// status='awaiting_user' (or interrupt state) as a candidate.
const now = Date.now();
const tasks = Array.isArray($input.first().json) ? $input.first().json : [];
const out = [];
for (const t of tasks) {
  const status = t.status || (t.next || []).length ? 'awaiting_user' : null;
  if (status !== 'awaiting_user') continue;
  const createdMs = t.created_at ? Date.parse(t.created_at) : (t.checkpoint_ts ? Date.parse(t.checkpoint_ts) : now);
  const ageMin = (now - createdMs) / 60000;
  let tier = null;
  if (ageMin >= 60 * 24 * 7) tier = '7d';
  else if (ageMin >= 60 * 4) tier = '4h';
  else if (ageMin >= 30) tier = '30min';
  if (!tier) continue; // not aged enough yet
  if (t.timeout_tier === tier) continue; // already at this tier
  out.push({ json: { task_id: t.task_id || t.thread_id || t.id, tier, age_min: Math.round(ageMin) } });
}
return out;
